Bash(node -e "
const fs = require\('fs'\);
const content = fs.readFileSync\('scripts/seed-test-data.ts', 'utf8'\);

// Count workflow definitions
const workflowIds = [...content.matchAll\(/id: \\"\(mock-[^\\"]+\)\\"/g\)].map\(m => m[1]\);
// Filter to unique entries in MOCK_WORKFLOWS \(not in GOVERNANCE_MATRIX\)
const govIds = [...content.matchAll\(/\\"\(mock-[^\\"]+\)\\": \\{/g\)].map\(m => m[1]\);

console.log\('Workflow IDs found:', workflowIds.length\);
console.log\('Governance entries:', govIds.length\);
console.log\('Workflow IDs:', JSON.stringify\([...new Set\(workflowIds\)]\)\);
console.log\('Governance IDs:', JSON.stringify\([...new Set\(govIds\)]\)\);

// Check for mismatches
const wfSet = new Set\(workflowIds\);
const govSet = new Set\(govIds\);
for \(const id of govSet\) {
  if \(!wfSet.has\(id\)\) console.log\('  GOV BUT NO WF:', id\);
}
for \(const id of wfSet\) {
  if \(!govSet.has\(id\)\) console.log\('  WF BUT NO GOV:', id\);
}
")
